<?php require __DIR__.'/../app/bootstrap.php';security_headers();$exists=(bool)database()->query('SELECT 1 FROM admin_users LIMIT 1')->fetchColumn();$e='';if($_SERVER['REQUEST_METHOD']==='POST'&&!$exists){if(!verify_csrf('setup',$_POST['_csrf']??null)||!hash_equals($config['setup_key'],(string)($_POST['setup_key']??'')))$e='Invalid setup key.';elseif(!filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL)||strlen($_POST['password']??'')<12)$e='Use a valid email and a password with at least 12 characters.';else{$n=utc_now();database()->prepare('INSERT INTO admin_users(email,password_hash,created_at,updated_at)VALUES(?,?,?,?)')->execute([strtolower(trim($_POST['email'])),password_hash($_POST['password'],PASSWORD_DEFAULT),$n,$n]);header('Location: /admin/login.php',true,303);exit;}}?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/template/page.css"><title>Setup</title></head><body><main class="section"><h1>Initial administrator</h1><?php if($exists):?><p>Setup is disabled because an administrator already exists.</p><?php else:?><p>Remove setup_key from config/local.php after use.</p><p><?=h($e)?></p><form method="post" class="interest-form"><input type="hidden" name="_csrf" value="<?=h(csrf_token('setup'))?>"><label class="public-field"><span>Setup key</span><input name="setup_key" required></label><label class="public-field"><span>Email</span><input name="email" type="email" required></label><label class="public-field"><span>Password</span><input name="password" type="password" minlength="12" required></label><button class="button">Create administrator</button></form><?php endif;?></main></body></html>
